import { Apps } from '@mui/icons-material';
import {
  Avatar,
  Button,
  ClickAwayListener,
  Fade,
  IconButton,
  Link,
  Paper,
  Popper,
  Typography,
  useMediaQuery,
  useTheme
} from '@mui/material';
import { useCallback, useState, type MouseEvent } from 'react';
import { useAppSwitcher } from '../hooks/useAppSwitcher';

// The text column, sized by the longest app name rather than the logo. Gutters are added on top of it so that
// density scales the space between tiles instead of eating into the room the label has to lay out in.
const TILE_WIDTH = 104;

export const AppSwitcher = () => {
  const theme = useTheme();
  const appSwitcher = useAppSwitcher();
  const isDarkTheme = theme.palette.mode === 'dark';
  const sp1 = theme.spacing(1);
  const tileWidth = `calc(${TILE_WIDTH}px + ${sp1} * 2)`;
  const isSm = useMediaQuery(theme.breakpoints.down('sm'));
  // App logos are artwork, not spacing: unlike a label they cannot reflow, so density gets a legibility floor.
  const avatarSize = `max(${theme.spacing(8)}, 40px)`;

  const [open, setOpen] = useState<boolean>(false);
  const [anchorEl, setAnchorEl] = useState<HTMLButtonElement>();

  const onTogglePopper = useCallback((event: MouseEvent<HTMLButtonElement>) => {
    setOpen(_open => !_open);
    setAnchorEl(event.currentTarget);
  }, []);

  const onClickAway = useCallback(() => setOpen(false), []);

  if (appSwitcher.empty) {
    return null;
  }

  return (
    <ClickAwayListener onClickAway={onClickAway}>
      <IconButton color="inherit" onClick={onTogglePopper} size="large">
        <Apps />
        <Popper
          sx={{ zIndex: theme.zIndex.drawer + 2 }}
          open={open && !!anchorEl}
          anchorEl={anchorEl}
          placement="bottom-end"
          transition
        >
          {({ TransitionProps }) => (
            <Fade {...TransitionProps} timeout={250}>
              <Paper style={{ textAlign: 'center', padding: theme.spacing(1) }} elevation={4}>
                <div
                  style={{
                    display: 'flex',
                    flexDirection: 'row',
                    flexWrap: 'wrap',
                    maxWidth: `calc(${tileWidth} * ${appSwitcher.items.length <= 4 || isSm ? 2 : 3})`
                  }}
                >
                  {appSwitcher.items.map((a, i) => (
                    <div key={`box-${i}`} style={{ width: tileWidth, padding: sp1, overflow: 'hidden' }}>
                      <Button
                        component={Link}
                        target={a.newWindow ? '_blank' : null}
                        href={a.route}
                        key={`button-${i}`}
                        style={{
                          display: 'flex',
                          flexDirection: 'column',
                          alignItems: 'center',
                          gap: theme.spacing(0.5),
                          // The tile already supplies the gutter; the button's own padding would take it out of the label.
                          paddingLeft: 0,
                          paddingRight: 0,
                          minWidth: 0,
                          textDecoration: 'none',
                          fontWeight: 400,
                          color: 'inherit'
                        }}
                      >
                        <div style={{ display: 'inline-flex' }}>
                          <Avatar
                            key={`avatar-${i}`}
                            variant="rounded"
                            alt={a.name}
                            src={
                              isDarkTheme
                                ? typeof a.img_d === 'string'
                                  ? a.img_d
                                  : null
                                : typeof a.img_l === 'string'
                                  ? a.img_l
                                  : null
                            }
                            style={
                              a.img_d === null || typeof a.img_d === 'string'
                                ? { width: avatarSize, height: avatarSize }
                                : { backgroundColor: 'transparent', width: avatarSize, height: avatarSize }
                            }
                            sx={{
                              '& img': {
                                objectFit: 'contain'
                              }
                            }}
                          >
                            {isDarkTheme
                              ? a.img_d !== null && typeof a.img_d !== 'string'
                                ? a.img_d
                                : a.alt
                              : a.img_l !== null && typeof a.img_l !== 'string'
                                ? a.img_l
                                : a.alt}
                          </Avatar>
                        </div>
                        <Typography
                          key={`text-${i}`}
                          variant="caption"
                          noWrap
                          title={a.name}
                          // Without a definite width the flex item takes its content width, so a long name grows
                          // past the tile and the tile's overflow clips it on both sides of the centred text.
                          sx={{ width: '100%' }}
                        >
                          {a.name}
                        </Typography>
                      </Button>
                    </div>
                  ))}
                </div>
              </Paper>
            </Fade>
          )}
        </Popper>
      </IconButton>
    </ClickAwayListener>
  );
};
